package com.lianxibu.site.controller.learning;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.lianxibu.site.service.identity.IdentityService;
import com.lianxibu.site.service.learning.OwnerAnswerReadService;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
class OwnerAnswerControllerTest {
 IdentityService auth;OwnerAnswerReadService service;ObjectProvider<OwnerAnswerReadService> provider;MockMvc mvc;final IdentityService.Actor owner=new IdentityService.Actor("fictional-owner","owner");
 @BeforeEach @SuppressWarnings("unchecked") void setup(){auth=mock(IdentityService.class);service=mock(OwnerAnswerReadService.class);var identity=(ObjectProvider<IdentityService>)mock(ObjectProvider.class);provider=mock(ObjectProvider.class);when(identity.getIfAvailable()).thenReturn(auth);when(provider.getIfAvailable()).thenReturn(service);when(auth.authenticate("fictional-session")).thenReturn(owner);mvc=MockMvcBuilders.standaloneSetup(new OwnerAnswerController(identity,provider)).build();}
 static String path(){return "/admin/learning/packages/fictional-package/questions/fictional-question/answer";}
 static jakarta.servlet.http.Cookie cookie(){return new jakarta.servlet.http.Cookie("lianxibu_session","fictional-session");}
 @Test void cookieOwnerPrecedesQueryAndService()throws Exception{mvc.perform(get(path()).param("unknown","fictional")).andExpect(status().isUnauthorized()).andExpect(header().string("Cache-Control","no-store"));when(auth.authenticate("fictional-session")).thenReturn(new IdentityService.Actor("fictional-user","user"));mvc.perform(get(path()).cookie(cookie()).param("unknown","fictional")).andExpect(status().isForbidden());verifyNoInteractions(service);}
 @Test void queryClosedAndMissingCompositionOrStorageIsUnavailable()throws Exception{mvc.perform(get(path()).cookie(cookie()).param("cursor","fictional")).andExpect(status().isBadRequest());verifyNoInteractions(service);when(provider.getIfAvailable()).thenReturn(null);mvc.perform(get(path()).cookie(cookie())).andExpect(status().isServiceUnavailable()).andExpect(header().string("Retry-After","1"));when(provider.getIfAvailable()).thenReturn(service);for(RuntimeException e:List.of(new OwnerAnswerReadService.Missing(),new OwnerAnswerReadService.Denied(),new IllegalArgumentException("Fictional internal detail"),new IllegalStateException("Fictional internal detail"))){doThrow(e).when(service).read(owner,"fictional-package","fictional-question");var result=mvc.perform(get(path()).cookie(cookie())).andExpect(status().is(e instanceof OwnerAnswerReadService.Missing?404:e instanceof OwnerAnswerReadService.Denied?403:e instanceof IllegalArgumentException?422:503)).andReturn();assertFalse(result.getResponse().getContentAsString().contains("internal detail"));}}
 @Test void actualServiceReturnsDraftUnknownAndNoReviewBytesOrHistory()throws Exception{var actual=new OwnerAnswerReadService((p,q)->new OwnerAnswerReadService.Snapshot(p,q,"Fictional question",3L,2L,"draft","generated","Fictional draft",true,null,true,true));when(provider.getIfAvailable()).thenReturn(actual);mvc.perform(get(path()).cookie(cookie())).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.data.answer").value("Fictional draft")).andExpect(jsonPath("$.data.publicly_readable").value(false)).andExpect(jsonPath("$.data.review_hash").doesNotExist()).andExpect(jsonPath("$.data.history").doesNotExist());when(provider.getIfAvailable()).thenReturn(new OwnerAnswerReadService((p,q)->new OwnerAnswerReadService.Snapshot(p,q,null,null,null,null,null,null,false,null,null,null)));mvc.perform(get(path()).cookie(cookie())).andExpect(status().isOk()).andExpect(jsonPath("$.data.revision").value(org.hamcrest.Matchers.nullValue())).andExpect(jsonPath("$.data.review_state").value("unknown"));}
 @Test void maximalUnicodeIsWholeAndUnprovenProjectionCannotLeak()throws Exception{when(provider.getIfAvailable()).thenReturn(new OwnerAnswerReadService((p,q)->new OwnerAnswerReadService.Snapshot(p,q,null,3L,null,"draft",null,"🙂".repeat(50000),true,null,true,true)));var response=mvc.perform(get(path()).cookie(cookie())).andExpect(status().isOk()).andReturn().getResponse();assertTrue(response.getContentAsByteArray().length<1024*1024);var data=tools.jackson.databind.json.JsonMapper.shared().readTree(response.getContentAsByteArray()).get("data");assertEquals(50000,data.get("answer").textValue().codePointCount(0,100000));when(provider.getIfAvailable()).thenReturn(service);when(service.read(owner,"fictional-package","fictional-question")).thenReturn(Map.of("package_id","fictional-other","question_id","fictional-question","answer","Fictional must not leak"));var wrong=mvc.perform(get(path()).cookie(cookie())).andExpect(status().isServiceUnavailable()).andReturn();assertFalse(wrong.getResponse().getContentAsString().contains("must not leak"));}
}
